import { toIsoTimestamp } from \"@/types/common\";
import type { BillingInterval, Subscription } from \"@/types/billing\";
import type { IsoTimestamp } from \"@/types/common\";

const MS_PER_DAY = 86_400_000;

/** Advance in UTC, preserving the time and clamping to the target month's last day. */
export function billingPeriodEnd(start: Date, interval: BillingInterval): IsoTimestamp {
  const end = new Date(start);
  const day = end.getUTCDate();
  end.setUTCDate(1);
  end.setUTCMonth(end.getUTCMonth() + (interval === \"annual\" ? 12 : 1));
  const lastDay = new Date(end);
  lastDay.setUTCMonth(lastDay.getUTCMonth() + 1, 0);
  end.setUTCDate(Math.min(day, lastDay.getUTCDate()));
  return toIsoTimestamp(end);
}

export function monthsPerPeriod(interval: BillingInterval): number {
  return interval === \"annual\" ? 12 : 1;
}

export function prorateCharge(amountCents: number, period: Subscription, now: Date): number {
  const end = new Date(period.currentPeriodEnd).getTime();
  const daysLeft = Math.max(0, Math.ceil((end - now.getTime()) / MS_PER_DAY));
  const daysInPeriod = Math.max(1, Math.round(
    (end - new Date(period.currentPeriodStart).getTime()) / MS_PER_DAY,
  ));
  return Math.floor(Math.max(0, amountCents) * daysLeft / daysInPeriod);
}
