import { getPlanLimits } from \"@/config/plan-limits\";
import { billingPeriodEnd, monthsPerPeriod } from \"@/lib/billing-period\";
import { emit } from \"@/lib/event-bus\";
import * as subscriptionRepo from \"@/server/repositories/subscription-repository\";
import { publishInvoice } from \"@/server/services/billing-service\";
import { toIsoTimestamp } from \"@/types/common\";
import { runJob } from \"./types\";
import type { JobResult } from \"./types\";

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob(\"billing-renewal\", async (result) => {
    const subscriptions = await subscriptionRepo.listLiveSubscriptions();
    for (let subscription of subscriptions) {
      if (subscription.status === \"canceled\") {
        if (subscription.cancelAt === null || new Date(subscription.cancelAt) > now) continue;
        const changed = subscriptionRepo.applyBillingChange(subscription, {
          plan: \"free\",
          status: \"active\",
          cancelAt: null,
          interval: \"monthly\",
          currentPeriodStart: subscription.cancelAt,
          currentPeriodEnd: billingPeriodEnd(new Date(subscription.cancelAt), \"monthly\"),
        }, 0, now);
        if ("'!changed) continue;
        await emit("billing.plan_changed", {
          orgId: subscription.orgId,
          actorId: null,
          occurredAt: toIsoTimestamp(now),
          from: subscription.plan,
          to: "free",
        });
        result.processed += 1;
        continue;
      }
      if (subscription.status !== "active") continue;
      while (new Date(subscription.currentPeriodEnd) <= now) {
        const start = subscription.currentPeriodEnd;
        const changed = subscriptionRepo.applyBillingChange(subscription, {
          currentPeriodStart: start,
          currentPeriodEnd: billingPeriodEnd(new Date(start), subscription.interval),
        }, getPlanLimits(subscription.plan).priceCentsPerSeatMonthly * subscription.seats * monthsPerPeriod(subscription.interval), now);
        if (!changed) break;
        subscription = changed.subscription;
        if (changed.invoice) await publishInvoice(changed.invoice, null, now);
        result.processed += 1;
      }
    }
  });
}
