    ["2026-02-28T12:30:45.123Z", "monthly", "2026-03-28T12:30:45.123Z"],
    ["2024-02-29T12:30:45.123Z", "annual", "2025-02-28T12:30:45.123Z"],
    ["2026-12-31T12:30:45.123Z", "monthly", "2027-01-31T12:30:45.123Z"],
