    expect(invoices).toHaveLength(3);
    expect(invoices.map((invoice) => invoice.periodStart)).toEqual([
      "2026-04-01T12:30:00.000Z", "2026-03-01T12:30:00.000Z", "2026-02-01T12:30:00.000Z",
