    expect(invoices.every((invoice) => invoice.amountCents === 1800 && invoice.currency === "usd" && invoice.paidAt === null)).toBe(true);
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);
    expect(issued).toHaveLength(3);
