/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const now = new Date();
  const current = requireFound(await subscriptionRepo.findSubscription(input.orgId), "Subscription", input.orgId);
  const currentPlan = current.plan;

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const startsPaidPeriod = current.plan === "free" && input.plan !== "free" && current.status !== "trialing";
  const price = getPlanLimits(input.plan).priceCentsPerSeatMonthly;
  const difference = price - getPlanLimits(current.plan).priceCentsPerSeatMonthly;
  const amountCents = startsPaidPeriod
    ? price * current.seats * monthsPerPeriod(input.interval)
    : current.status === "active" && current.plan !== "free" && input.plan !== "free"
      ? prorateCharge(difference * current.seats * monthsPerPeriod(current.interval), current, now)
      : 0;
  const changed = subscriptionRepo.applyBillingChange(current, {
    plan: input.plan,
    interval: input.interval,
    status: current.status === "trialing" && input.plan !== "free" ? "trialing" : "active",
    cancelAt: null,
    ...(startsPaidPeriod ? {
      currentPeriodStart: toIsoTimestamp(now),
      currentPeriodEnd: billingPeriodEnd(now, input.interval),
    } : {}),
  }, amountCents, now);
  if (!changed) throw new Error("Subscription changed concurrently; please retry");
  const { subscription, invoice } = changed;
  if (invoice) await publishInvoice(invoice, actor.userId, now);

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const now = new Date();
  const current = requireFound(await subscriptionRepo.findSubscription(input.orgId), "Subscription", input.orgId);
  const plan = current.plan;

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const amountCents = current.status === "active" && plan !== "free"
    ? prorateCharge(
      getPlanLimits(plan).priceCentsPerSeatMonthly * Math.max(0, input.seats - current.seats) * monthsPerPeriod(current.interval),
      current, now,
    ) : 0;
  const changed = subscriptionRepo.applyBillingChange(current, { seats: input.seats }, amountCents, now);
  if (!changed) throw new Error("Subscription changed concurrently; please retry");
  if (changed.invoice) await publishInvoice(changed.invoice, actor.userId, now);
  return changed.subscription;
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

