/** Cross-tenant sweep without a batch limit; archived workspaces never participate. */
export async function listLiveSubscriptions(): Promise<readonly Subscription[]> {
  return getDb().select({ subscription: subscriptions }).from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(shouldFilterArchived() ? isNull(organizations.archivedAt) : undefined).all()
    .map(({ subscription }) => toSubscription(subscription));
}

type BillingPatch = Partial<Pick<Subscription,
  "plan" | "interval" | "status" | "seats" | "currentPeriodStart" | "currentPeriodEnd" | "cancelAt"
>>;

/** Compare the original state and commit the charge and change atomically. */
export function applyBillingChange(
  current: Subscription,
  patch: BillingPatch,
  amountCents: number,
  now: Date,
): { subscription: Subscription; invoice: Invoice | null } | null {
  const db = getDb();
  return db.transaction(() => {
    const row = db.select().from(subscriptions)
      .where(and(eq(subscriptions.id, current.id), orgPredicate(subscriptions.orgId, current.orgId))).get();
    if (!row) throw new Error(`Subscription for org ${current.orgId} not found`);
    const fields = ["plan", "interval", "status", "seats", "currentPeriodStart", "currentPeriodEnd", "cancelAt", "updatedAt"] as const;
    if (fields.some((field) => row[field] !== current[field])) return null;

    const stamp = toIsoTimestamp(now);
    const updated = db.update(subscriptions).set({ ...patch, updatedAt: stamp })
      .where(eq(subscriptions.id, current.id)).returning().get();
    if (patch.plan !== undefined) {
      db.update(organizations).set({ plan: patch.plan, updatedAt: stamp })
        .where(eq(organizations.id, current.orgId)).run();
    }
    const subscription = toSubscription(updated);
    const invoice = amountCents > 0 ? createInvoice(
      current.orgId, amountCents, subscription.currentPeriodStart, subscription.currentPeriodEnd, now,
    ) : null;
    return { subscription, invoice };
  });
}
import { getPlanLimits } from "@/config/plan-limits";
import { billingPeriodEnd, monthsPerPeriod } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { publishInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "./types";

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listLiveSubscriptions();
    for (let subscription of subscriptions) {
      if (subscription.status === "canceled") {
        if (subscription.cancelAt === null || new Date(subscription.cancelAt) > now) continue;
        const changed = subscriptionRepo.applyBillingChange(subscription, {
          plan: "free",
          status: "active",
          cancelAt: null,
          interval: "monthly",
          currentPeriodStart: subscription.cancelAt,
          currentPeriodEnd: billingPeriodEnd(new Date(subscription.cancelAt), "monthly"),
        }, 0, now);
        if (!changed) continue;
        await emit("billing.plan_changed", {
          orgId: subscription.orgId,
          actorId: null,
          occurredAt: toIsoTimestamp(now),
          from: subscription.plan,
          to: "free",
        });
        subscription = changed.subscription;
        result.processed += 1;
      }
      if (subscription.status !== "active") continue;
      while (new Date(subscription.currentPeriodEnd) <= now) {
        const start = subscription.currentPeriodEnd;
        const changed = subscriptionRepo.applyBillingChange(subscription, {
          currentPeriodStart: start,
          currentPeriodEnd: billingPeriodEnd(new Date(start), subscription.interval),
        }, getPlanLimits(subscription.plan).priceCentsPerSeatMonthly * subscription.seats * monthsPerPeriod(subscription.interval), now);
        if (!changed) break;
        subscription = changed.subscription;
        if (changed.invoice) await publishInvoice(changed.invoice, null, now);
        result.processed += 1;
      }
    }
  });
}
